# RFC 7396 merge patch: null deletes, object merges, anything else replaces
import json

def merge_patch(target, patch):
    if not isinstance(patch, dict):
        return patch                      # non-object replaces the target
    if not isinstance(target, dict):
        target = {}                       # start from an empty object
    result = dict(target)
    for key, value in patch.items():
        if value is None:
            result.pop(key, None)         # null means delete the key
        else:
            result[key] = merge_patch(result.get(key), value)
    return result

doc = {"name": "Ann", "tags": ["a", "b"], "address": {"city": "Oslo", "zip": "0150"}}
patch = {"name": None, "tags": ["c"], "address": {"zip": "0151"}}

print("doc   :", json.dumps(doc))
print("patch :", json.dumps(patch))
once = merge_patch(doc, patch)
print("result:", json.dumps(once))
# Idempotent: applying the same patch again changes nothing
print("again :", json.dumps(merge_patch(once, patch)))
# tags became ["c"]: arrays are replaced, never edited element by element
# Time O(size of patch), space O(size of result)

