// Optimistic concurrency with ETag / If-Match
const res = { value: "draft", version: 1 };      // server state
const etag = () => '"v' + res.version + '"';

function put(ifMatch, newValue) {
  if (!ifMatch) return 428;                      // Precondition Required
  if (ifMatch !== etag()) return 412;            // someone else changed it
  res.value = newValue;                          // check and write are one step
  res.version += 1;                              // new ETag after every write
  return 200;
}

const aliceTag = etag();                         // both clients GET v1
const bobTag = etag();
console.log("start:", JSON.stringify(res), "ETag", aliceTag);
console.log("no header   ->", put(null, "x"));
console.log("Alice PUT   ->", put(aliceTag, "alice"));
console.log("Bob PUT old ->", put(bobTag, "bob"));   // stale tag
console.log("end:", JSON.stringify(res), "ETag", etag());
// Bob must re-GET, merge, and retry with the new tag. O(1) per request.
